def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # The interior is a horizontally repeating row pattern. Find its period
    # from the visible cells, then use each row's visible cells to fill gaps.
    for r in range(h):
        if r < 2:
            for c in range(w):
                if grid[r][c] == 0:
                    out[r][c] = 1
            continue
        if r == 2:
            for c in range(w):
                if grid[r][c] == 0:
                    out[r][c] = 4
            continue

        known = [(c, grid[r][c]) for c in range(3, w) if grid[r][c] != 0]
        period = None
        for p in range(1, w):
            if all(grid[r][c] == grid[r][c2]
                   for c, c2 in ((a, b) for a, _ in known
                                 for b, _ in known if (a-b) % p == 0)):
                period = p
                break
        if period is None:
            period = 5

        # Build a value lookup by column modulo the inferred period.
        vals = {}
        for c, v in known:
            vals[c % period] = v
        for c in range(3, w):
            if grid[r][c] == 0:
                out[r][c] = vals[c % period]

        # The left frame is fixed background.
        for c in range(3):
            if grid[r][c] == 0:
                out[r][c] = 1 if c < 2 else 4
    return out
